#[test]
fn a_v3_ring_and_a_v4_ring_do_not_attach_to_each_other() {
    use crate::mpsc::v3;
    let mut r = Region::new();
    let (base, len) = region(&mut r);
    let (first_v3, first_v4) = with_init_pool(base, len, |pool| {
        let ring_v3 = v3::MpscRing::<v3::Multi>::init(pool, 64, 4, 2).unwrap();
        let ring_v4 = MpscRing::<Multi>::init(pool, 64, 4, 2).unwrap();
        (ring_v3.first_segment(), ring_v4.first_segment())
    });
    let b = attach_pool(base, len);
    // SAFETY: each index came from first_segment of a ring over this pool, whose segments are
    // still that ring's.
    unsafe {
        assert_eq!(
            MpscRing::<Multi>::attach(&b, first_v3).err(),
            Some(Error::BadMagic)
        );
        assert_eq!(
            v3::MpscRing::<v3::Multi>::attach(&b, first_v4).err(),
            Some(Error::BadMagic)
        );
        assert!(MpscRing::<Multi>::attach(&b, first_v4).is_ok());
        assert!(v3::MpscRing::<v3::Multi>::attach(&b, first_v3).is_ok());
    }
}

