impl<T, W: Wake> MpscReadSlot<'_, T, W> {
    /// Free the slot for reuse.
    ///
    /// - The position advances first, private state, and the seq store last (`Release`), the
    ///   protocol-visible handoff producers acquire.
    /// - Every half segment of releases, producers asleep on a full ring are woken, when the
    ///   [`Wake`] wakes: a fence per half segment, not per message.
    pub fn release(self) {
        let st = self.st;
        let segs = &st.segs;
        let c = st.pos;
        st.pos = seq_of(c.wrapping_add(1));
        segs.seq(st.cur, c)
            .store(seq_of(c.wrapping_add(segs.capacity)), Ordering::Release);
        if W::WAKES && st.pos & segs.wake_mask == 0 {
            segs.wake_producers::<W>();
        }
    }
}

