    /// - `Err(Empty)`: the ring stayed empty until `give_up` passed. `read_msg` was not called.
    #[cfg(any(target_os = "linux", feature = "std"))]
    pub fn recv_spin<T, R>(
        &mut self,
        give_up: Ticks,
        read_msg: impl FnOnce(&T) -> R,
    ) -> Result<R, Empty>
    where
        T: FromBytes + KnownLayout + Immutable,
    {
