            |_, _| {
                if give_up != Ticks::FOREVER {
                    let now = now_ticks();
                    if now >= *end.get_or_insert(now.saturating_add(give_up.0)) {
                        return false;
                    }
                }
                core::hint::spin_loop();
                true
            },
            read_msg,
        )
    }

