    #[cfg(any(target_os = "linux", feature = "std"))]
    pub fn recv_spin_sleep<T, R>(
        &mut self,
        spin_time: Ticks,
        sleep_time: Ticks,
        read_msg: impl FnOnce(&T) -> R,
    ) -> Result<R, Empty>
