/// - [`NoWake`] is `Spins`: nothing sleeps, no endpoint checks for a sleeper, and a spin costs
///   nothing but itself.
/// - [`Futex`] is not `Spins`: an endpoint that spins without end on such a ring pays the checks
///   for sleepers and gains nothing from them. [`Mixed`] is the wake that says so on purpose.
pub trait Spins: Wake {}

/// `trait Sleeps` marks a [`Wake`] whose ring's endpoints may sleep. `mpsc::v4` offers
/// `send_spin_sleep` and `recv_spin_sleep` on a ring whose wake is `Sleeps`.
///
/// - [`Futex`] is `Sleeps`.
/// - [`NoWake`] is not `Sleeps`: its sleep is one spin hint, so a sleep on such a ring would be a
///   spin under another name.
pub trait Sleeps: Wake {}

impl Spins for NoWake {}

#[cfg(target_os = "linux")]
impl<const TIMEOUT_MS: u32> Sleeps for Futex<TIMEOUT_MS> {}

/// `struct Mixed` is the wake `W` for a ring on which some endpoints spin without end while others
/// sleep, a mix made on purpose. `Mixed<W>` sleeps and wakes exactly as `W` does.
///
/// - The cost: on any ring whose wake sleeps, every endpoint checks for sleepers, a producer after
///   each commit and the consumer at each half segment of messages read, whether or not anyone
///   sleeps. The endpoint that pays is the one awake, and the one that gains is the one asleep, so
///   an endpoint that only spins pays for the others' sleep. Measured on one machine as about 3 ns
///   of a 46 ns round trip between two threads.
/// - `Mixed<W>` is [`Spins`] and [`Sleeps`], so a ring over it offers every timed send and receive.
///   A ring over `W` alone offers the spin and sleep forms only, and a ring over [`NoWake`] the
///   spin forms only.
/// - `Mixed<W>` and `W` are one wake protocol: a process attached with one and a process attached
///   with the other share a ring correctly. The name is a statement in one process's types.
pub struct Mixed<W: Sleeps>(PhantomData<W>);

impl<W: Sleeps> Wake for Mixed<W> {
    const WAKES: bool = W::WAKES;

    fn wait(seen: Seen<'_>) {
        W::wait(seen);
    }

    fn wait_until(seen: Seen<'_>, deadline: Deadline) {
        W::wait_until(seen, deadline);
    }

    fn wake(word: &AtomicU32) {
        W::wake(word);
    }
}

impl<W: Sleeps> Spins for Mixed<W> {}

impl<W: Sleeps> Sleeps for Mixed<W> {}
